# KQM Vodyanitsa quick guide, Varka team: Vodyanitsa E > Prune EQ > Mona
# Q N1 E N3 > Varka combo, as written. The rotation gives Vodyanitsa no
# burst; she bursts after her skill when ready (the guide: her burst is
# lowest priority).
# Varka's combo is the harvested Varka / Prune / Mona / Furina team's
# (teams/varka-prune-mona-furina), its combo for rotations without
# Furina's burst (the longer one stretches the rotation for her buff).
active vodyanitsa;
vodyanitsa skill;
if .vodyanitsa.burst.ready {
  vodyanitsa burst;
}
prune skill, burst;
mona burst, attack, skill, attack:3;
varka skill,
      attack, charge, walk,
      attack:4, skill,
      attack, charge, walk,
      attack, charge, walk,
      attack, charge, walk,
      attack, skill,
      attack:2;

active varka; 
let walk_cancel=true; 
fn walk_or_not() {
  if walk_cancel {
    varka walk;
  }
}
for let i=0; i<6; i=i+1 {
  durin skill:2, burst;
  prune skill, burst;
  nicole skill, burst;
  varka skill;
  varka attack;  
  if .varka.cons == 0 {
    varka charge;  walk_or_not();
  } else {
    varka skill;
  }
  varka attack:4, skill;
  varka attack:4, skill;
  varka attack;
  varka charge;  walk_or_not();
  if .nicole.weapon == .keys.weapon.ttds { 
    varka attack:2;
    varka charge;
    if .varka.cons != 0 {
      delay(3); 
    }
    if .varka.weapon == .keys.weapon.gestofthemightywolf {
      if walk_cancel==true {
        delay(5);
      }
    }
  } else {
    varka attack;
  }
}

active mona;
